pnpm -s exec tsx -e 'import { parseBytecodeModule } from "./src/bytecodeReader"; import fs from "fs";
const PC2LINE_BASE=-1, PC2LINE_RANGE=5, PC2LINE_OP_FIRST=1;
function readULEB(data:Uint8Array, st:{i:number}){let r=0,sh=0; while(st.i<data.length){const b=data[st.i++]; r|=(b&0x7f)<<sh; if((b&0x80)===0) break; sh+=7;} return r>>>0;}
function readSLEB(data:Uint8Array, st:{i:number}){let r=0,sh=0,b=0; do{b=data[st.i++]; r|=(b&0x7f)<<sh; sh+=7;}while((b&0x80)!==0); if(sh<32 && (b&0x40)!==0){r|=(~0<<sh);} return r|0;}
function decode(pc2:Uint8Array){const st={i:0}; const initLine=readULEB(pc2,st); const initCol=readULEB(pc2,st); let pc=0,line=initLine,col=initCol; const out:any[]=[{pc,line,col,kind:"init"}]; while(st.i<pc2.length){const op=pc2[st.i++]; if(op===0){ if(st.i>=pc2.length){out.push({kind:"end"}); break;} const dpc=readULEB(pc2,st); const dl=readSLEB(pc2,st); const dc=readSLEB(pc2,st); pc+=dpc; line+=dl; col+=dc; out.push({pc,line,col,op:"long",dpc,dl,dc}); } else { const opVal=op-PC2LINE_OP_FIRST; const dpc=Math.floor(opVal/PC2LINE_RANGE); const dl=(opVal%PC2LINE_RANGE)+PC2LINE_BASE; const dc=readSLEB(pc2,st); pc+=dpc; line+=dl; col+=dc; out.push({pc,line,col,op:"short",dpc,dl,dc,raw:op}); } } return out;}
function inner(mod:any){const cp=mod.func.cpool||[]; return cp.find((e:any)=>e && typeof e==="object" && e.tag===12);
}
function show(name:string, pc2:Uint8Array){console.log(`\n=== ${name} len=${pc2.length} ===`); console.log(Array.from(pc2).map(b=>b.toString(16).padStart(2,"0")).join(" ")); console.log(decode(pc2));}
const ts=parseBytecodeModule(fs.readFileSync("artifacts/optional-chaining.ts.qbc"));
const wasm=parseBytecodeModule(fs.readFileSync("artifacts/optional-chaining.wasm.qbc"));
show("TS outer", ts.func.debug!.pc2line);
show("WASM outer", wasm.func.debug!.pc2line);
show("TS inner", inner(ts).debug.pc2line);
show("WASM inner", inner(wasm).debug.pc2line);
'

pnpm -s exec tsx -e "import ts from 'typescript'; import {readFileSync} from 'node:fs'; import { DebugInfoBuilder } from './src/compiler/DebugInfoBuilder'; import { GetLineColCache } from './src/compiler/FunctionDef'; const file='__tests__/fixtures/class-methods.ts'; const code=readFileSync(file,'utf8'); const out=ts.transpileModule(code,{fileName:file, compilerOptions:{module: ts.ModuleKind.ESNext,target: ts.ScriptTarget.ESNext}}).outputText; const cache=new GetLineColCache(); cache.ptr=0; cache.lineNum=1; cache.colNum=0; cache.bufStart=0; let maxCol=-1; let maxPos=-1; for(let pos=0; pos<out.length; pos++){ const c2=new GetLineColCache(); Object.assign(c2, cache); // not use cached; do fresh each time
 const [ln, col]=DebugInfoBuilder.getLineColCached(c2,out,pos);
 if(ln===6 && col>maxCol){ maxCol=col; maxPos=pos; }
 }
 console.log({maxCol, maxPos});"

pnpm -s exec tsx -e "const PC2LINE_BASE=-1,PC2LINE_RANGE=5,PC2LINE_OP_FIRST=1; const readULEB=(data,o)=>{let r=0,s=0; for(;;){const b=data[o.i++]; r|=(b&0x7f)<<s; if(!(b&0x80)) break; s+=7;} return r>>>0;}; const readZigZag=(data,o)=>{const u=readULEB(data,o); return ((u>>>1) ^ -(u&1))|0;}; function decode(name,data){const o={i:0}; let pc=0; let line=readULEB(data,o); let col=readULEB(data,o); console.log('\n'+name,'init', {pc,line,col}); while(o.i<data.length){const op=data[o.i++]; let dpc,dline; if(op===0){dpc=readULEB(data,o); dline=readZigZag(data,o);} else {const enc=op-PC2LINE_OP_FIRST; dpc=Math.floor(enc/PC2LINE_RANGE); dline=(enc%PC2LINE_RANGE)+PC2LINE_BASE;} const dcol=readZigZag(data,o); pc+=dpc; line+=dline; col+=dcol; console.log({pc,line,col,dpc,dline,dcol,op:'0x'+op.toString(16)}); } }
const ts=[0x05,0x04,0x0d,0x08,0x07,0x18,0x1b,0x04,0x07,0x03,0x26,0x01,0x1b,0x15];
const wasm=[0x05,0x04,0x0d,0x08,0x07,0x08,0x1b,0x14,0x07,0x05,0x26,0x00,0x1b,0x15];
decode('TS',ts); decode('WASM',wasm);"
